public final class Solution {
    private Solution() {}

    public enum PayloadKind { TEXT, IMAGE, SOUND }
    public enum DeliveryState { NEW, SENDING, DELIVERED, FAILED }

    public static final class Note {
        private final String id;
        private final long timestamp;
        private final String sender;
        private final PayloadKind kind;
        private final String content;
        private DeliveryState state = DeliveryState.NEW;
        private boolean read;

        public Note(String id, long timestamp, String sender, PayloadKind kind, String content) {
            if (id == null || id.trim().isEmpty() || timestamp < 0 || sender == null
                    || sender.trim().isEmpty() || kind == null || content == null) {
                throw new IllegalArgumentException();
            }
            this.id = id.trim();
            this.timestamp = timestamp;
            this.sender = sender.trim();
            this.kind = kind;
            this.content = content;
        }

        public String id() { return id; }
        public long timestamp() { return timestamp; }
        public String sender() { return sender; }
        public PayloadKind kind() { return kind; }
        public String content() { return content; }
        public synchronized DeliveryState state() { return state; }
        public synchronized boolean isRead() { return read; }

        public synchronized boolean beginSend() {
            if (state != DeliveryState.NEW) return false;
            state = DeliveryState.SENDING;
            return true;
        }

        public synchronized boolean deliver() {
            if (state != DeliveryState.SENDING) return false;
            state = DeliveryState.DELIVERED;
            return true;
        }

        public synchronized boolean fail() {
            if (state != DeliveryState.NEW && state != DeliveryState.SENDING) return false;
            state = DeliveryState.FAILED;
            return true;
        }

        public synchronized boolean markRead() {
            if (state != DeliveryState.DELIVERED || read) return false;
            read = true;
            return true;
        }

        public synchronized String toString() {
            return kind + "|" + content + "|" + sender + "|" + state + "|read=" + read;
        }
    }
}
